ALTER TABLE "copias_seccion" ADD CONSTRAINT "copias_seccion_creada_por_usuarios_id_usuario_fk" FOREIGN KEY ("creada_por") REFERENCES "public"."usuarios"("id_usuario") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "copias_seccion_seccion_idx" ON "copias_seccion" USING btree ("seccion","creada_en");--> statement-breakpoint
